def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    frames=[]
    colors={v for row in grid for v in row if v!=0}
    for color in colors:
        pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
        r0=min(r for r,c in pts); r1=max(r for r,c in pts)
        c0=min(c for r,c in pts); c1=max(c for r,c in pts)
        if r1-r0<2 or c1-c0<2: continue
        if all(grid[r][c]==color for r in range(r0,r1+1) for c in range(c0,c1+1)
               if r in (r0,r1) or c in (c0,c1)):
            pat=[row[c0+1:c1] for row in grid[r0+1:r1]]
            frames.append((color,r0,c0,r1-r0-1,c1-c0-1,pat))
    for color,r,c,ih,iw,pat in frames:
        if any(v!=0 for row in pat for v in row):
            for dest,rr,cc,hh,ww,dpat in frames:
                if (hh,ww)==(ih,iw) and not any(v!=0 for row in dpat for v in row):
                    for dr in range(ih):
                        for dc in range(iw):
                            if pat[dr][dc]!=0:
                                out[rr+1+dr][cc+1+dc]=dest
    return out
