def transform2(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    frames=[]
    for color in {v for row in grid for v in row if v!=0}:
        pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
        r0=min(r for r,c in pts); r1=max(r for r,c in pts)
        c0=min(c for r,c in pts); c1=max(c for r,c in pts)
        if r1-r0<2 or c1-c0<2: continue
        if all(grid[r][c]==color for r in range(r0,r1+1) for c in range(c0,c1+1)
               if r in (r0,r1) or c in (c0,c1)):
            pat=[grid[rr][c0+1:c1] for rr in range(r0+1,r1)]
            frames.append((color,r0,c0,r1-r0-1,c1-c0-1,pat))
    templates={}
    for f in frames:
        color,r,c,ih,iw,pat=f
        if any(v!=0 for row in pat for v in row): templates.setdefault((ih,iw),pat)
    active=set(templates)
    for color,r,c,ih,iw,pat in frames:
        if (ih,iw) not in active:
            for rr in range(r,r+ih+2):
                for cc in range(c,c+iw+2): out[rr][cc]=0
        elif not any(v!=0 for row in pat for v in row):
            src=templates[(ih,iw)]
            for dr in range(ih):
                for dc in range(iw):
                    if src[dr][dc]!=0: out[r+1+dr][c+1+dc]=color
    return out
